-- ========================================================
-- MySQL Seed Script for Amazon Capstone Project
-- Generated from image_mapping.csv (1000 Products & Images)
-- ========================================================

USE capstone_db;

-- 1. Insert Categories
ON DUPLICATE KEY UPDATE display_name=VALUES(display_name);

-- 2. Insert Products (1000 items)
ON DUPLICATE KEY UPDATE name=VALUES(name), price=VALUES(price), primary_image=VALUES(primary_image);

-- 3. Insert Product Images (1000 items mapped to products table)
ON DUPLICATE KEY UPDATE image_url=VALUES(image_url);
